const input = $input.first().json;

// Очищення зайвих лапок
function c(val) {
  if (val === null || val === undefined) return val;
  if (typeof val !== 'string') return val;
  return val.replace(/^"(.*)"$/s, '$1');
}

const rawText = input.output || input.text || input.response || '';

const clean = rawText
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    draft_message:   '',
    mentor_summary:  '',
    dashboard_label: '⚠️ Потребує уваги',
  };
}

const prev = $('Communicator Trigger').first().json;
const data = prev.body || prev;

return [{
  json: {
    ...data,

    // Очищаємо лапки
    draft_message:   c(parsed.draft_message)   || '',
    mentor_summary:  c(parsed.mentor_summary)  || '',
    dashboard_label: c(parsed.dashboard_label) || '⚠️ Потребує уваги',
  }
}];

const input = $input.first().json;

// Математично визначаємо label по priority і action
const labelMap = {
  critical: {
    mentor_call:           '🚨 КРИТИЧНО — дзвінок сьогодні',
    escalation_to_manager: '🚨 КРИТИЧНО — ескалація менеджеру',
  },
  high: {
    mentor_call:           '⚠️ Потребує дзвінка від ментора',
    personal_message:      '⚠️ Надіслати повідомлення сьогодні',
  },
  medium: {
    personal_message:      '💬 М\'який дотик цього тижня',
    additional_material:   '📚 Надати додатковий матеріал',
    mentor_call:           '📞 Запланувати дзвінок',
  },
  low: {
    no_action:             '✅ Все гаразд — моніторинг',
  },
};

const priority = input.priority || 'low';
const action   = input.recommended_action || 'no_action';

const label = labelMap[priority]?.[action]
  || labelMap['low']['no_action'];

return [{
  json: {
    ...input,
    dashboard_label: label,
  }
}];;

const input = $input.first().json;
const data  = input.body || input;

const student  = data.student          || {};
const observer = data.observer_result  || {};
const computed = data.computed_signals || {};

const promptText =
  'Згенеруй комунікацію для студента.\n\n' +

  'СТУДЕНТ: ' + (student.name || '?') + '\n' +
  'КУРС: ' + (student.course || '?') + '\n\n' +

  'СИТУАЦІЯ:\n' +
  '- student_state: ' + (data.student_state || '?') + '\n' +
  '- recommended_action: ' + (data.recommended_action || '?') + '\n' +
  '- priority: ' + (data.priority || '?') + '\n' +
  '- timing: ' + (data.timing || '?') + '\n' +
  '- days_to_dropout: ' + (data.days_to_dropout_estimate || '?') + '\n\n' +

  'ПРИЧИНИ РИЗИКУ:\n' +
  (data.primary_drivers || []).map(d => '- ' + d).join('\n') + '\n\n' +

  'ОБҐРУНТУВАННЯ СТРАТЕГІЇ:\n' +
  (data.rationale || '') + '\n\n' +

  'ОСТАННІ ПОВІДОМЛЕННЯ СТУДЕНТА:\n' +
  (data.recent_messages || []).join('\n') + '\n\n' +

  'Поверни ТІЛЬКИ валідний JSON без markdown:\n' +
  '{\n' +
  '  "draft_message": "<2-3 речення без цифр і тиску>",\n' +
  '  "mentor_summary": "<1-2 речення для ментора>",\n' +
  '  "dashboard_label": "<коротка фраза для картки>"\n' +
  '}';

return [{
  json: {
    ...data,
    prompt_text: promptText,
  }
}];
